mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.RG_DT DESC) AS LISTNUM, USER_ID, USER_NM, PPCD, RG_SCCD, HOLD_SCCD, ATTY_CFY, CASE WHEN ATTY_CFY = '001' THEN '전체관리자' WHEN ATTY_CFY = '002' THEN '사업소관리자' ELSE '' END AS ATTY_CFY_NM, RELTN_SCTN_NM, RMK, REGPR_ID, REGPR_NM, RG_DT, TO_CHAR(RG_DT, 'YYYY-MM-DD') AS FM_RG_DT FROM GE_MP_USER_M A WHERE 1 = 1
AND A.PPCD = #{SH_PPCD}
ORDER BY RG_DT DESC ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

SELECT COUNT(*) FROM GE_MP_USER_M A WHERE 1 = 1
AND A.PPCD = #{SH_PPCD}
ORDER BY RG_DT DESC
